"""Bounded CPU-only supervisor; worker bytes are embedded for Kaggle scripts."""
from __future__ import annotations

import base64
from datetime import datetime, timezone
import hashlib
import json
import os
from pathlib import Path
import resource
import signal
import subprocess
import sys
import time

ABSOLUTE_CUTOFF = "2026-10-25T07:35:00+00:00"
SESSION_TIMEOUT_SECONDS = 900
CLEANUP_SECONDS = 20
WORKER_SHA256 = '97db7d400101b8ed254e7b60bfbbbec8fb375b1e9f028474dfffb58eaa0b8766'
WORKER_BASE64 = ''
OUTPUT = Path("/kaggle/working/target_recovery")


def atomic_json(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    with temporary.open("w", encoding="utf-8") as stream:
        json.dump(value, stream, sort_keys=True, indent=2, allow_nan=False)
        stream.write("\n")
        stream.flush()
        os.fsync(stream.fileno())
    os.replace(temporary, path)


def main():
    started, wall_started = time.perf_counter(), datetime.now(timezone.utc)
    cutoff = datetime.fromisoformat(ABSOLUTE_CUTOFF).timestamp()
    compute_deadline = min(time.time() + SESSION_TIMEOUT_SECONDS, cutoff) - CLEANUP_SECONDS
    receipt = {"format": "molgap-cpu-target-recovery-entry-v1", "status": "RUNNING",
        "wall_start_utc": wall_started.isoformat(), "absolute_cutoff_utc": ABSOLUTE_CUTOFF,
        "session_timeout_seconds_required_at_submission": SESSION_TIMEOUT_SECONDS,
        "cleanup_reserve_seconds": CLEANUP_SECONDS, "worker_sha256": WORKER_SHA256,
        "entry_sha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
        "requested_accelerator": "CPU", "queue_hours": {"value": None, "status": "measurement_missing"},
        "gpu_hours": {"value": None, "status": "not_applicable"},
        "scope": "Entry through worker termination; platform queue and release excluded"}
    atomic_json(OUTPUT / "entry_receipt.json", receipt)
    process = None
    try:
        if time.time() >= compute_deadline:
            raise TimeoutError("Absolute cutoff leaves no CPU work window")
        payload = base64.b64decode(WORKER_BASE64, validate=True)
        if hashlib.sha256(payload).hexdigest() != WORKER_SHA256:
            raise ValueError("Embedded worker digest differs")
        executable = Path("/kaggle/temp/molgap-target-recovery-worker.py")
        executable.parent.mkdir(parents=True, exist_ok=True)
        executable.write_bytes(payload)
        env = {**os.environ, "CUDA_VISIBLE_DEVICES": "-1", "OMP_NUM_THREADS": "2", "MKL_NUM_THREADS": "2"}
        process = subprocess.Popen([sys.executable, str(executable), "--input", "/kaggle/input",
            "--output", str(OUTPUT), "--work", "/kaggle/temp/molgap-target-recovery",
            "--deadline", str(compute_deadline)], env=env, start_new_session=True)
        code = process.wait(timeout=max(0.01, compute_deadline - time.time()))
        if code != 0:
            raise RuntimeError("CPU recovery worker exit " + str(code))
        if not (OUTPUT / "manifest.json").is_file():
            raise ValueError("Worker exited without complete export manifest")
        receipt["status"] = "COMPLETE"
        receipt["manifest_sha256"] = hashlib.sha256((OUTPUT / "manifest.json").read_bytes()).hexdigest()
    except BaseException as exc:
        receipt.update(status="STOP_FOR_COST" if isinstance(exc, (TimeoutError, subprocess.TimeoutExpired)) else "FAILED",
                       error={"type": type(exc).__name__, "message": str(exc)})
        if process is not None and process.poll() is None:
            os.killpg(process.pid, signal.SIGTERM)
            try:
                process.wait(timeout=10)
            except subprocess.TimeoutExpired:
                os.killpg(process.pid, signal.SIGKILL)
                process.wait(timeout=5)
        raise
    finally:
        observation = OUTPUT / "worker_observation.json"
        if observation.is_file():
            receipt["worker_observation_sha256"] = hashlib.sha256(observation.read_bytes()).hexdigest()
        own, children = resource.getrusage(resource.RUSAGE_SELF), resource.getrusage(resource.RUSAGE_CHILDREN)
        cpu = own.ru_utime + own.ru_stime + children.ru_utime + children.ru_stime
        receipt.update(wall_end_utc=datetime.now(timezone.utc).isoformat(),
            wall_seconds=time.perf_counter() - started,
            measured_process_tree_cpu_seconds=cpu,
            cpu_hours={"value": cpu / 3600, "status": "measured" if receipt["status"] == "COMPLETE" else "measurement_missing"},
            cpu_scope="Entry and reaped children; interruption may omit unreaped descendants",
            worker_returncode=None if process is None else process.poll())
        if receipt["status"] != "COMPLETE":
            receipt["cpu_hours"]["value"] = None
        atomic_json(OUTPUT / "entry_receipt.json", receipt)


if __name__ == "__main__":
    main()
